import{_ as t,o as h,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Nguyên tắc Chỉ Truyền lại Kiến thức","description":"","frontmatter":{},"headers":[],"relativePath":"vi/0087-仅回传知识原则.md","filePath":"vi/0087-仅回传知识原则.md"}'),g={name:"vi/0087-仅回传知识原则.md"};function a(u,n,o,l,r,m){return h(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="nguyen-tac-chi-truyen-lai-kien-thuc" tabindex="-1">Nguyên tắc Chỉ Truyền lại Kiến thức <a class="header-anchor" href="#nguyen-tac-chi-truyen-lai-kien-thuc" aria-label="Permalink to &quot;Nguyên tắc Chỉ Truyền lại Kiến thức&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>87</td></tr><tr><td>Mô-đun</td><td>Tương tác Liên mặt phẳng và Quy tắc Thời gian</td></tr><tr><td>Từ khóa cốt lõi</td><td>Chỉ truyền lại kiến thức, tinh chế thông tin, cấm truyền lại vật chất, mã hóa kiến thức, kiểm toán truyền lại</td></tr></tbody></table><h2 id="_1-boi-canh-lap-phap-va-tu-tuong-cot-loi-cua-nguyen-tac" tabindex="-1">1. Bối cảnh lập pháp và Tư tưởng cốt lõi của Nguyên tắc <a class="header-anchor" href="#_1-boi-canh-lap-phap-va-tu-tuong-cot-loi-cua-nguyen-tac" aria-label="Permalink to &quot;1. Bối cảnh lập pháp và Tư tưởng cốt lõi của Nguyên tắc&quot;">​</a></h2><p>Nguyên tắc &quot;chỉ truyền lại kiến thức&quot; là một trong những nguyên tắc cơ bản của khảo cổ liên mặt phẳng và lùi lại thời gian của văn minh cộng sinh neo, nguồn gốc pháp lý của nó có thể truy ngược về Điều 48 của &quot;Hiến pháp Cộng sinh&quot;: &quot;Bất kỳ vật chất, năng lượng và sinh vật nào thu được từ mặt phẳng khác hoặc khoảng thời gian khác, không được mang vào mặt phẳng自己 mà không có sự cho phép đặc biệt; sản phẩm hợp pháp của hoạt động khảo cổ chỉ giới hạn ở kiến thức và thông tin trừu tượng.&quot; Việc thiết lập nguyên tắc này là một lựa chọn thể chế mà Hengyuanzhou đưa ra sau khi tổng kết những bài học đau đớn từ việc khám phá liên mặt phẳng ban đầu.</p><p>Vào giai đoạn đầu thành lập văn minh cộng sinh neo, việc khám phá liên mặt phẳng vẫn còn trong trạng thái vô trật tự. Một số nhà thám hiểm đã mang mẫu vật chất, tinh thể năng lượng và thậm chí cả sinh vật từ các mặt phẳng khác về mặt phẳng自己 để nghiên cứu, đã gây ra nhiều &quot;sự cố ô nhiễm liên mặt phẳng&quot; nghiêm trọng. Trường hợp nổi tiếng nhất là &quot;Sự cố Tinh thể lạ&quot; — một tinh thể năng lượng được mang về từ mặt phẳng biểu hiện năng lượng, do tham số luật của nó không tương thích với mặt phẳng自己, đã gây ra sự rối loạn luật kéo dài ba năm trong mạng lưới luật của mặt phẳng自己, dẫn đến bất thường trong hệ thống tu luyện của ba vùng sao, và hàng chục ngàn người tu luyện đã bị tổn thương ở các mức độ khác nhau. Điều tra sau đó cho thấy rằng nếu lúc đó tuân theo nguyên tắc &quot;chỉ truyền lại kiến thức&quot;, thảm họa này hoàn toàn có thể tránh được.</p><p>Tư tưởng cốt lõi của nguyên tắc &quot;chỉ truyền lại kiến thức&quot; là: kiến thức là phương tiện duy nhất an toàn trong giao lưu giữa các văn minh. Vật chất và năng lượng mang thông tin luật của mặt phẳng nguồn gốc của chúng, sau khi xâm nhập vào môi trường luật khác nhau có thể gây ra phản ứng không thể dự đoán; còn kiến thức như là thông tin trừu tượng, sau khi được mã hóa và tinh chế phù hợp, có thể tách dấu vết luật của mặt phẳng nguồn gốc, và trở thành nguồn lực an toàn có thể chia sẻ giữa các mặt phẳng.</p><h2 id="_2-đinh-nghia-va-phan-loai-kien-thuc" tabindex="-1">2. Định nghĩa và Phân loại &quot;Kiến thức&quot; <a class="header-anchor" href="#_2-đinh-nghia-va-phan-loai-kien-thuc" aria-label="Permalink to &quot;2. Định nghĩa và Phân loại &quot;Kiến thức&quot;&quot;">​</a></h2><p>Dưới khuôn khổ pháp lý của nguyên tắc &quot;chỉ truyền lại kiến thức&quot;, &quot;kiến thức&quot; có định nghĩa và phân loại nghiêm ngặt. Không phải mọi thông tin đều có thể được coi là &quot;kiến thức&quot; và truyền lại tự do — chỉ những thông tin trừu tượng đã经过 quy trình &quot;tinh chế thông tin&quot; và được xác nhận không mang bất kỳ ô nhiễm luật nào mới đáp ứng tiêu chuẩn truyền lại.</p><p>Kiến thức được chia thành ba loại theo mức độ trừu tượng và mức độ an toàn:</p><table tabindex="0"><thead><tr><th>Loại kiến thức</th><th>Định nghĩa</th><th>Mức độ an toàn</th><th>Yêu cầu truyền lại</th></tr></thead><tbody><tr><td>Kiến thức cấp một (kiến thức trừu tượng thuần túy)</td><td>Khái niệm trừu tượng hoàn toàn tách rời khỏi vật chất mang, định lý toán học, suy luận logic, tư tưởng triết học, v.v.</td><td>Cao nhất (xanh lá)</td><td>Có thể truyền lại trực tiếp, không cần phê duyệt đặc biệt</td></tr><tr><td>Kiến thức cấp hai (kiến thức mô tả)</td><td>Thông tin mô tả về sự vật khách quan, bao gồm hồ sơ lịch sử, dữ liệu địa lý, đặc điểm sinh học, mô tả văn hóa, v.v.</td><td>Trung bình (vàng)</td><td>Phải经过 quy trình tinh chế thông tin, truyền lại sau khi được Cục Quản lý Mặt phẳng phê duyệt</td></tr><tr><td>Kiến thức cấp ba (kiến thức kỹ thuật)</td><td>Kiến thức thực tế chứa tham số kỹ thuật cụ thể, kế hoạch kỹ thuật, phương pháp tu luyện</td><td>Thấp hơn (cam)</td><td>Phải经过 tinh chế thông tin nghiêm ngặt và đánh giá an toàn, truyền lại sau khi được Hội đồng Neo phê duyệt đặc biệt</td></tr></tbody></table><p>Các nội dung sau đây不属于 phạm trù &quot;kiến thức&quot;, và bị nghiêm cấm truyền lại: mẫu vật chất dưới bất kỳ hình thức nào (bao gồm vi sinh vật, tế bào, đoạn gen), tinh thể năng lượng hoặc thiết bị lưu trữ năng lượng dưới bất kỳ hình thức nào, bất kỳ sinh vật hoặc thể ý thức nào có ý thức tự chủ, bất kỳ dữ liệu gốc nào chưa经过 tinh chế thông tin, và bất kỳ chi tiết kỹ thuật nào có thể được sử dụng cho việc tu luyện cướp bóc.</p><h2 id="_3-cong-nghe-tinh-che-thong-tin" tabindex="-1">3. Công nghệ Tinh chế Thông tin <a class="header-anchor" href="#_3-cong-nghe-tinh-che-thong-tin" aria-label="Permalink to &quot;3. Công nghệ Tinh chế Thông tin&quot;">​</a></h2><p>Tinh chế thông tin là khâu kỹ thuật then chốt để đảm bảo an toàn của kiến thức được truyền lại. Mục tiêu cốt lõi của nó là tách hoàn toàn dấu vết luật của mặt phẳng nguồn gốc mang trong thông tin gốc, chỉ giữ lại nội dung ngữ nghĩa thuần túy. Quá trình tinh chế thông tin được chia thành bốn bước:</p><h3 id="_3-1-giai-cau-truc-thong-tin" tabindex="-1">3.1 Giải cấu trúc Thông tin <a class="header-anchor" href="#_3-1-giai-cau-truc-thong-tin" aria-label="Permalink to &quot;3.1 Giải cấu trúc Thông tin&quot;">​</a></h3><p>Đầu tiên, thông tin gốc cần truyền lại được giải cấu trúc một cách có cấu trúc, chia thành hai phần: &quot;nội dung ngữ nghĩa&quot; và &quot;dấu vết mang&quot;. Nội dung ngữ nghĩa là ý nghĩa trừu tượng mà thông tin muốn thể hiện, dấu vết mang là các tham số luật của mặt phẳng nguồn gốc mà thông tin hấp thụ trong quá trình lưu trữ và truyền dẫn. Giải cấu trúc thông tin实现 thông qua &quot;thuật toán tách ngữ nghĩa-mang&quot;, thuật toán này có thể nhận dạng và tách thành phần ngữ nghĩa và thành phần luật trong thông tin.</p><h3 id="_3-2-tach-luat" tabindex="-1">3.2 Tách luật <a class="header-anchor" href="#_3-2-tach-luat" aria-label="Permalink to &quot;3.2 Tách luật&quot;">​</a></h3><p>Thực hiện tách luật hoàn toàn đối với dấu vết mang đã được tách. Phương pháp tách là đưa thông tin qua &quot;kênh trung hòa luật&quot; — đây là một kênh truyền dẫn đặc biệt có tham số luật được đặt là hoàn toàn trung tính, khi thông tin đi qua, tất cả các tham số luật không trung tính mà nó mang sẽ bị thành kênh hấp thụ. Sau khi tách luật, thông tin không còn mang bất kỳ dấu vết luật nào của mặt phẳng nguồn gốc.</p><h3 id="_3-3-xay-dung-lai-ngu-nghia" tabindex="-1">3.3 Xây dựng lại Ngữ nghĩa <a class="header-anchor" href="#_3-3-xay-dung-lai-ngu-nghia" aria-label="Permalink to &quot;3.3 Xây dựng lại Ngữ nghĩa&quot;">​</a></h3><p>Trên cơ sở tách luật, thực hiện mã hóa lại nội dung ngữ nghĩa, sử dụng hệ thống mã hóa thông tin tiêu chuẩn của mặt phẳng自己 để xây dựng lại thông tin. Việc xây dựng lại ngữ nghĩa đảm bảo rằng kiến thức được truyền lại có thể được đọc và hiểu đúng trong môi trường luật của mặt phẳng自己,同时 cũng进一步 loại bỏ bất kỳ cấu trúc thông tin nào của mặt phẳng nguồn gốc có thể còn sót lại.</p><h3 id="_3-4-phat-hien-an-toan" tabindex="-1">3.4 Phát hiện An toàn <a class="header-anchor" href="#_3-4-phat-hien-an-toan" aria-label="Permalink to &quot;3.4 Phát hiện An toàn&quot;">​</a></h3><p>Thông tin sau khi tinh chế phải经过 phát hiện an toàn nghiêm ngặt, bao gồm: phát hiện dư lượng luật (xác nhận thông tin không mang bất kỳ tham số luật nước ngoài nào), phát hiện tính toàn vẹn ngữ nghĩa (xác nhận quy trình tinh chế không làm thay đổi nội dung ngữ nghĩa của thông tin), và đánh giá rủi ro tiềm ẩn (đánh giá tác động xã hội và an toàn mà việc lan truyền kiến thức này trong mặt phẳng自己 có thể mang lại). Chỉ những thông tin vượt qua cả ba phát hiện mới được phép truyền lại.</p><h2 id="_4-quy-trinh-truyen-lai-va-he-thong-kiem-toan" tabindex="-1">4. Quy trình Truyền lại và Hệ thống Kiểm toán <a class="header-anchor" href="#_4-quy-trinh-truyen-lai-va-he-thong-kiem-toan" aria-label="Permalink to &quot;4. Quy trình Truyền lại và Hệ thống Kiểm toán&quot;">​</a></h2><p>Việc truyền lại kiến thức tuân theo quản lý quy trình nghiêm ngặt. Một hoạt động truyền lại hoàn chỉnh bao gồm các khâu sau:</p><ol><li><strong>Tổ chức Kiến thức</strong>: Đội khảo cổ tổ chức kết quả nghiên cứu thành tài liệu kiến thức được tiêu chuẩn hóa, ghi rõ loại kiến thức và tóm tắt nội dung.</li><li><strong>Đơn xin Tinh chế</strong>: Nộp đơn xin tinh chế và truyền lại kiến thức cho Cục Quản lý Mặt phẳng hoặc Ủy ban Luật Thời gian, kèm theo tài liệu kiến thức và tệp giấy phép nhiệm vụ khảo cổ.</li><li><strong>Tinh chế Thông tin</strong>: Đội ngũ kỹ thuật tinh chế thông tin chuyên nghiệp thực hiện quy trình tinh chế thông tin bốn bước đối với tài liệu kiến thức.</li><li><strong>Phát hiện An toàn</strong>: Kiến thức sau khi tinh chế经过 ba phát hiện do cơ quan phát hiện an toàn độc lập thực hiện.</li><li><strong>Phê duyệt và Truyền lại</strong>: Sau khi vượt qua phát hiện, cơ quan phê duyệt ký giấy phép truyền lại, kiến thức được truyền lại đến cơ sở dữ liệu kiến thức của mặt phẳng自己 thông qua kênh mã hóa của mạng lưới neo.</li><li><strong>Lưu trữ vào Kho</strong>: Kiến thức được truyền lại经过 xác minh của kho kiến thức mặt phẳng自己 sau đó chính thức được lưu trữ vào kho, mở cho các nhà nghiên cứu có thẩm quyền phù hợp.</li></ol><p>Tất cả các hoạt động truyền lại đều phải接受 &quot;kiểm toán truyền lại&quot;. Nội dung kiểm toán bao gồm: nguồn gốc của kiến thức được truyền lại có hợp pháp hay không, quy trình tinh chế có đúng quy范 hay không, phát hiện an toàn có hoàn chỉnh hay không, thủ tục phê duyệt có đúng quy范 hay không. Kiểm toán do Văn phòng Kiểm toán Truyền lại Kiến thức thuộc Ủy ban Giám sát Neo chịu trách nhiệm, mỗi quý thực hiện kiểm tra mẫu đối với tất cả các hoạt động truyền lại trong quý đó, và mỗi năm thực hiện một lần kiểm toán toàn diện. Kết quả kiểm toán được báo cáo cho Hội đồng Neo, và bản tóm tắt được công khai cho công chúng.</p><h2 id="_5-hanh-vi-vi-pham-va-trach-nhiem-phap-ly" tabindex="-1">5. Hành vi Vi phạm và Trách nhiệm Pháp lý <a class="header-anchor" href="#_5-hanh-vi-vi-pham-va-trach-nhiem-phap-ly" aria-label="Permalink to &quot;5. Hành vi Vi phạm và Trách nhiệm Pháp lý&quot;">​</a></h2><p>Các hành vi vi phạm nguyên tắc &quot;chỉ truyền lại kiến thức&quot; bao gồm: tự ý truyền lại thông tin chưa tinh chế mà không có phê duyệt, ngụy trang mẫu vật chất thành kiến thức để truyền lại, cố tình che giấu dấu vết luật của mặt phẳng nguồn gốc trong kiến thức được truyền lại, và hỗ trợ người khác thực hiện truyền lại bất hợp pháp.</p><p>Theo &quot;Hiến pháp Cộng sinh&quot; và &quot;Luật Quản lý Tương tác Liên mặt phẳng&quot;, trách nhiệm pháp lý đối với hành vi truyền lại vi phạm bao gồm: tịch thu vật phẩm và thông tin được truyền lại vi phạm, đình chỉ hoặc thu hồi tư cách khảo cổ và di chuyển của bên liên quan, phạt tiền tương đương với hơn 10 lần giá trị của vật phẩm vi phạm, đối với trường hợp nghiêm trọng thì xử phạt tù, nếu gây ra ô nhiễm luật hoặc phá hủy sinh thái thì phải chịu toàn bộ chi phí sửa chữa và trách nhiệm bồi thường.</p><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Nguyên tắc &quot;chỉ truyền lại kiến thức&quot; là đường đáy trí tuệ của văn minh cộng sinh neo trong lĩnh vực tương tác liên mặt phẳng. Với định nghĩa nghiêm ngặt, công nghệ tinh chế trưởng thành, quy trình truyền lại đúng quy范 và trách nhiệm pháp lý nghiêm khắc, nó đã xây dựng một &quot;tường lửa an toàn kiến thức&quot; vững chắc. Ý nghĩa của nguyên tắc này không chỉ在于 ngăn chặn ô nhiễm ở cấp độ vật lý, mà quan trọng hơn là đã thiết lập một quan điểm đạo đức về giao lưu văn minh — sự giao tiếp giữa các văn minh nên lấy sự va chạm tư tưởng làm cốt lõi, chứ không phải lấy mục đích cướp bóc vật chất.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>84-Tổng cương Nghị định thư Khảo cổ</li><li>88-Nguyên tắc Đạo đức Liên mặt phẳng</li><li>66-Công nghệ Truyền thông Liên mặt phẳng</li></ul>',32)])])}const y=t(g,[["render",a]]);export{e as __pageData,y as default};
